// ============ KONFIGURASI — ubah di sini ============
// Mapping email e-statement -> konfigurasi bank untuk esta.
// Key dicocokkan sebagai SUBSTRING (huruf kecil) terhadap
// NAMA+ALAMAT PENGIRIM dan SUBJEK email.
// bank_type valid: bca, mandiri, mandiri_email, dbs, ccbca,
//   ccmandiri, bri, saqu, blu
// password : password PDF e-statement (kosongkan jika tidak terkunci)
// company_id : UUID company di esta (opsional)
const SENDER_MAP = {
  'digibank': {bank_type: 'dbs', password: 'GANTI-DENGAN-PASSWORD-PDF', company_id: ''},

  // Tambahkan bank lain di sini nanti, contoh:
  // 'livin': { bank_type: 'mandiri_email', password: 'xxx', company_id: '' },
};

// Folder arsip di dalam container n8n (host: docker/n8n/data/files/gmail)
const SAVE_DIR = '/home/node/.n8n/files/gmail';
// =====================================================

// Ambil pengirim dari berbagai bentuk output node Gmail
// (string; objek mailparser {text,value,address}; headers raw).
function pickFrom(j) {
  const f = j.from !== undefined ? j.from : j.From;
  if (typeof f === 'string') return f;
  if (f && typeof f === 'object') {
    if (typeof f.text === 'string') return f.text;
    if (Array.isArray(f.value)) {
      return f.value.map((a) => (a && (a.address || a.name)) || '').filter(Boolean).join(', ');
    }
    if (typeof f.address === 'string') return f.address;
  }
  const h = (j.headers || {}).from || (j.headers || {}).From;
  if (typeof h === 'string') return h.replace(/^\s*from:\s*/i, '');
  return '';
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const fromRaw = pickFrom(j);
  const subject = String(
    j.subject !== undefined ? j.subject
      : (j.Subject !== undefined ? j.Subject : (j.headers || {}).subject || '')
  );
  const haystack = (fromRaw + ' ' + subject).toLowerCase();

  let cfg = null;
  let matched = '';
  for (const [key, value] of Object.entries(SENDER_MAP)) {
    if (haystack.includes(key.toLowerCase())) {
      cfg = value;
      matched = key;
      break;
    }
  }
  if (!cfg) continue; // email tidak dikenal — abaikan

  const when = j.internalDate
    ? new Date(Number(j.internalDate))
    : (j.date ? new Date(j.date) : new Date());
  const stampTime = isNaN(when.getTime()) ? new Date() : when;
  const stamp = stampTime.toISOString().replace(/[:.]/g, '-').slice(0, 19);
  const emailDate = j.date ? String(j.date) : (j.internalDate ? stampTime.toISOString() : '');

  for (const [prop, binary] of Object.entries(item.binary || {})) {
    const fileName = String(binary.fileName || binary.filename || 'statement.pdf');
    if (!/\.(pdf|csv)$/i.test(fileName)) continue; // hanya PDF & CSV
    const safeName = fileName.replace(/[^a-zA-Z0-9._-]/g, '_');
    out.push({
      json: {
        bank_type: cfg.bank_type,
        password: cfg.password || '',
        company_id: cfg.company_id || '',
        email_from: fromRaw.slice(0, 300),
        email_subject: subject.slice(0, 300),
        email_date: emailDate.slice(0, 300),
        message_id: String(j.id || j.messageId || ''),
        file_name: fileName,
        matched_sender: matched,
        save_path: SAVE_DIR + '/' + stamp + '_' + (out.length + 1) + '_' + safeName,
      },
      binary: { data: binary },
    });
  }
}
return out;
